-- Accounts: credentials and role, each bound 1:1 to a local actor. The username
-- is the join key to `actors`, so an account and its ActivityPub identity share
-- one name. UUID ids are generated by the application (uuid v4), so no database
-- extension is required.
CREATE TABLE accounts (
    id            UUID PRIMARY KEY,
    username      TEXT NOT NULL UNIQUE REFERENCES actors(username) ON DELETE CASCADE,
    role          TEXT NOT NULL,                 -- school | student | service
    display_name  TEXT,
    email         TEXT,
    password_hash TEXT NOT NULL,                 -- argon2 PHC string
    created_by    UUID REFERENCES accounts(id) ON DELETE SET NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX accounts_role_idx ON accounts (role);
CREATE INDEX accounts_created_by_idx ON accounts (created_by);
